const bindingSchema=z.object({format:z.literal(1),candidate:z.unknown(),requesterUserId:id,executorUserId:id,clientRequestId:z.string().uuid(),transportMode:z.enum(['controlled','provider'])}).strict();
type Binding=z.infer<typeof bindingSchema>;
const approval=z.object({actorUserId:id,actionDigest:z.string().regex(/^[a-f0-9]{64}$/),clientRequestId:z.string().uuid(),expectedVersion:z.number().int().min(0)}).strict();
const stateSchema=z.object({status:z.enum(['awaiting_approval','approved','dispatching','confirmed','refused','unknown','cancelled']),approval:approval.nullable(),issue:z.object({sysId:z.string().regex(/^[a-f0-9]{32}$/),number:z.string().regex(/^CHG[0-9]{1,20}$/)}).strict().nullable(),providerWritePerformed:z.boolean().nullable(),lastActionId:z.string().uuid().nullable(),lastExpectedVersion:z.number().int().min(0).nullable(),executionScope:scopeSchema.nullable(),recovery:serviceNowTicketRecoverySchema.optional()}).strict();
