 async function current(tx:ReleaseOperationPlanTransaction,scope:ServiceNowTicketScope,row:ReleaseOperationPlanRow,write:boolean,context:ServiceNowTicketSourceContext={phase:write?'before_dispatch':'prepare'}){const {b,c,s}=unpack(row,scope.organizationId);await authority(tx,scope,scope.actorUserId,write?'execute':'read',c,context.phase);await authority(tx,scope,b.requesterUserId,'read',c,context.phase);if(write){await writeReady(tx,scope,c);await authority(tx,scope,b.executorUserId,'execute',c,context.phase);if(!s.approval)refuse();await authority(tx,scope,s.approval!.actorUserId,'approve',c,context.phase)}await fresh(tx,scope,c,context);await published(tx,scope,c,b);await authority(tx,scope,scope.actorUserId,write?'execute':'read',c,context.phase);await clock(tx,c);return{b,c,s}}
 async function event(tx:ReleaseOperationPlanTransaction,row:ReleaseOperationPlanRow,actor:string,type?:'amended'|'recovery_requested'|'recovery_approved'|'recovery_verified'|'recovery_cancelled'){const {b,c,s}=unpack(row,row.organizationId);await tx.durableAgentWorkflowEvent.create({data:{workflowRunId:row.id,organizationId:row.organizationId,sequence:row.version,eventType:'servicenow_ticket.'+(type??row.currentStep),actorKind:'user',actorId:actor,detailJson:{actionDigest:sha256ContentHash(c),executorUserId:b.executorUserId,requesterUserId:b.requesterUserId,...(row.version===0||type==='amended'?{candidateSnapshot:structuredClone(c)}:{}),...(type?.startsWith('recovery_')?{recoverySnapshot:structuredClone(s.recovery)}:{}),clientRequestId:s.lastActionId,expectedVersion:s.lastExpectedVersion},occurredAt:now()}})}
