 function dto(row:ReleaseOperationPlanRow,scope:ServiceNowTicketScope){const {b,c,s}=unpack(row,scope.organizationId);return parseServiceNowTicketActionDto({id:row.id,version:row.version,releaseId:c.releaseId,kind:c.kind,status:s.status,payloadDigest:c.payloadDigest,createdAt:row.createdAt.toISOString(),expiresAt:c.expiresAt,attemptCount:row.attemptCount,issue:s.issue,canApprove:false,canExecute:false,canAmend:row.attemptCount===0&&row.version<17&&['awaiting_approval','approved','cancelled'].includes(s.status)&&scope.actorUserId===b.requesterUserId,canCancel:row.attemptCount===0&&['awaiting_approval','approved'].includes(s.status)&&[b.requesterUserId,s.approval?.actorUserId].includes(scope.actorUserId),providerWritePerformed:s.providerWritePerformed,transportMode:b.transportMode,review:review(c),...(s.recovery?{recovery:{...s.recovery,canApprove:false,canVerify:false,canCancel:false}}:{})})}
